-- ==============================================================================
-- WishWell Power BI Analytics Historical Dataset (6 Months)
-- File: /db/seed_analytics.sql
-- Generated: 300 Wishes, 150 Claims, 100 Deliveries, 100 Thank-You Notes
-- Compatible with Azure SQL Database & Microsoft SQL Server 2022
-- ==============================================================================

SET NOCOUNT ON;
GO

-- ------------------------------------------------------------------------------
-- STEP 1: Temporarily disable validation triggers for bulk historical seeding
-- ------------------------------------------------------------------------------
IF OBJECT_ID('dbo.trg_wishes_check_needed_by_future', 'TR') IS NOT NULL
    DISABLE TRIGGER dbo.trg_wishes_check_needed_by_future ON dbo.wishes;
IF OBJECT_ID('dbo.trg_wish_claims_enforce_active_qty_limit', 'TR') IS NOT NULL
    DISABLE TRIGGER dbo.trg_wish_claims_enforce_active_qty_limit ON dbo.wish_claims;
IF OBJECT_ID('dbo.trg_wishes_status_audit', 'TR') IS NOT NULL
    DISABLE TRIGGER dbo.trg_wishes_status_audit ON dbo.wishes;
IF OBJECT_ID('dbo.trg_wish_claims_status_audit', 'TR') IS NOT NULL
    DISABLE TRIGGER dbo.trg_wish_claims_status_audit ON dbo.wish_claims;
IF OBJECT_ID('dbo.trg_deliveries_status_audit', 'TR') IS NOT NULL
    DISABLE TRIGGER dbo.trg_deliveries_status_audit ON dbo.deliveries;
GO

-- ------------------------------------------------------------------------------
-- STEP 2: Insert 6 Months of Historical Wishes (~300 Wishes)
-- ------------------------------------------------------------------------------
SET IDENTITY_INSERT dbo.wishes ON;
GO

GO

GO

GO

GO

GO

GO

SET IDENTITY_INSERT dbo.wishes OFF;
GO

-- ------------------------------------------------------------------------------
-- STEP 3: Insert Historical Wish Claims (~150 Claims)
-- ------------------------------------------------------------------------------
SET IDENTITY_INSERT dbo.wish_claims ON;
GO

GO

GO

GO

SET IDENTITY_INSERT dbo.wish_claims OFF;
GO

-- ------------------------------------------------------------------------------
-- STEP 4: Insert Historical Deliveries (~100 Deliveries)
-- ------------------------------------------------------------------------------
SET IDENTITY_INSERT dbo.deliveries ON;
GO

GO

GO

SET IDENTITY_INSERT dbo.deliveries OFF;
GO

-- ------------------------------------------------------------------------------
-- STEP 5: Insert Historical Thank-You Notes
-- ------------------------------------------------------------------------------
SET IDENTITY_INSERT dbo.thank_you_notes ON;
GO

GO

GO

SET IDENTITY_INSERT dbo.thank_you_notes OFF;
GO

-- ------------------------------------------------------------------------------
-- STEP 6: Re-enable database validation & integrity triggers
-- ------------------------------------------------------------------------------
IF OBJECT_ID('dbo.trg_wishes_check_needed_by_future', 'TR') IS NOT NULL
    ENABLE TRIGGER dbo.trg_wishes_check_needed_by_future ON dbo.wishes;
IF OBJECT_ID('dbo.trg_wish_claims_enforce_active_qty_limit', 'TR') IS NOT NULL
    ENABLE TRIGGER dbo.trg_wish_claims_enforce_active_qty_limit ON dbo.wish_claims;
IF OBJECT_ID('dbo.trg_wishes_status_audit', 'TR') IS NOT NULL
    ENABLE TRIGGER dbo.trg_wishes_status_audit ON dbo.wishes;
IF OBJECT_ID('dbo.trg_wish_claims_status_audit', 'TR') IS NOT NULL
    ENABLE TRIGGER dbo.trg_wish_claims_status_audit ON dbo.wish_claims;
IF OBJECT_ID('dbo.trg_deliveries_status_audit', 'TR') IS NOT NULL
    ENABLE TRIGGER dbo.trg_deliveries_status_audit ON dbo.deliveries;
GO

-- ------------------------------------------------------------------------------
-- STEP 7: Create Read-Only SQL User for Power BI Desktop & Service
-- ------------------------------------------------------------------------------
IF NOT EXISTS (SELECT 1 FROM sys.database_principals WHERE name = 'powerbi_reader')
BEGIN
    CREATE USER [powerbi_reader] WITH PASSWORD = 'PowerBI_SecureReader2026!';
END
ELSE
BEGIN
    ALTER USER [powerbi_reader] WITH PASSWORD = 'PowerBI_SecureReader2026!';
END;
GO

GRANT SELECT ON dbo.vw_wishes_by_category_month TO [powerbi_reader];
GRANT SELECT ON dbo.vw_avg_delivery_time TO [powerbi_reader];
GRANT SELECT ON dbo.vw_institutions_by_status TO [powerbi_reader];
GRANT SELECT ON dbo.vw_stale_claim_rate TO [powerbi_reader];
GRANT SELECT ON dbo.vw_top_categories TO [powerbi_reader];
GRANT SELECT ON dbo.v_open_wishes TO [powerbi_reader];
GRANT SELECT ON dbo.categories TO [powerbi_reader];
GRANT SELECT ON dbo.institutions TO [powerbi_reader];
GRANT SELECT ON dbo.wishes TO [powerbi_reader];
GRANT SELECT ON dbo.wish_claims TO [powerbi_reader];
GRANT SELECT ON dbo.deliveries TO [powerbi_reader];
DENY INSERT, UPDATE, DELETE ON SCHEMA::dbo TO [powerbi_reader];
GO

PRINT '>>> Power BI Analytics 6-Month Seed Data Successfully Applied! <<<';
GO